window.REV_FLIP=window.REV_FLIP||{};window.REV_FLIP["docker"]=[{"id":"docker-f0001","card":"q-docker-001-docker-vs-a-virtual-machine","sec":"docker-s002","q":"What is Docker vs a VM?","a":"<ul>\n  <li><strong>Docker</strong>: lightweight containers that share the host OS kernel. Fast.</li>\n  <li><strong>VM</strong>: full OS emulation. Heavy and slower.</li>\n</ul>","hand":false},{"id":"docker-f0002","card":"q-docker-001-docker-vs-a-virtual-machine","sec":"docker-s002","q":"What are the advantages of Docker over virtualization?","a":"<p>Lightweight, fast, efficient, portable, scalable.</p>","hand":false},{"id":"docker-f0003","card":"q-docker-001-docker-vs-a-virtual-machine","sec":"docker-s002","q":"What is containerization, Docker's take?","a":"<p>The app and its dependencies packaged in one unit. Docker uses namespaces, cgroups and a union file system.</p>","hand":false},{"id":"docker-f0004","card":"q-docker-001-docker-vs-a-virtual-machine","sec":"docker-s002","q":"What problem does Docker solve?","a":"<p>Consistency across dev, test and prod. No \"works on my machine\" issues.</p>","hand":false},{"id":"docker-f0005","card":"q-docker-002-docker-architecture","sec":"docker-s003","q":"What are the key Docker architecture components?","a":"<ul>\n  <li><strong>Daemon</strong>: manages Docker objects.</li>\n  <li><strong>Client</strong>: the CLI.</li>\n  <li><strong>Images</strong>: templates.</li>\n  <li><strong>Containers</strong>: running instances.</li>\n  <li><strong>Registry</strong>: image store.</li>\n</ul>","hand":false},{"id":"docker-f0006","card":"q-docker-002-docker-architecture","sec":"docker-s003","q":"Container vs image?","a":"<ul>\n  <li><strong>Container</strong>: a running instance.</li>\n  <li><strong>Image</strong>: a static blueprint.</li>\n</ul>","hand":false},{"id":"docker-f0007","card":"q-docker-002-docker-architecture","sec":"docker-s003","q":"Image layer vs container layer?","a":"<ul>\n  <li><strong>Image</strong>: a read-only stack of layers.</li>\n  <li><strong>Container</strong>: a writable top layer.</li>\n</ul>","hand":false},{"id":"docker-f0008","card":"q-docker-002-docker-architecture","sec":"docker-s003","q":"What is the default storage driver and why does it matter?","a":"<p><strong>overlay2</strong> (the Linux default). It affects performance, storage and compatibility.</p>","hand":false},{"id":"docker-f0009","card":"q-docker-003-run-vs-start-vs-exec","sec":"docker-s004","q":"What is the difference between <code>docker run</code>, <code>start</code> and <code>exec</code>?","a":"<ul>\n  <li><strong>run</strong>: creates a new container and starts it.</li>\n  <li><strong>start</strong>: restarts a stopped container.</li>\n  <li><strong>exec</strong>: runs a command inside a running container.</li>\n</ul>","hand":false},{"id":"docker-f0010","card":"q-docker-004-checking-the-docker-version","sec":"docker-s005","q":"How do you check the Docker version?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker --version\ndocker version  # Full client/server info</code></pre></div>","hand":false},{"id":"docker-f0011","card":"q-docker-005-building-and-listing-images","sec":"docker-s006","q":"What is the role of a Dockerfile?","a":"<p>A script that builds images. It defines the base, dependencies and runtime.</p>","hand":false},{"id":"docker-f0012","card":"q-docker-005-building-and-listing-images","sec":"docker-s006","q":"How do you create an image from a Dockerfile?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker build -t myapp:1.0 .</code></pre></div>","hand":false},{"id":"docker-f0013","card":"q-docker-005-building-and-listing-images","sec":"docker-s006","q":"What happens in <code>docker build</code>?","a":"<p>It reads the Dockerfile, builds layers, caches them and tags the image.</p>","hand":false},{"id":"docker-f0014","card":"q-docker-005-building-and-listing-images","sec":"docker-s006","q":"How do you list all images?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker images\ndocker image ls</code></pre></div>","hand":false},{"id":"docker-f0015","card":"q-docker-005-building-and-listing-images","sec":"docker-s006","q":"How do you tag an image, and why?","a":"<p>For versioning and clarity.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker tag myapp myapp:1.0</code></pre></div>","hand":false},{"id":"docker-f0016","card":"q-docker-005-building-and-listing-images","sec":"docker-s006","q":"How do you remove unused images?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker image rm &lt;id&gt;\ndocker image prune -a</code></pre></div>","hand":false},{"id":"docker-f0017","card":"q-docker-006-dockerfile-instructions","sec":"docker-s007","q":"What are the common Dockerfile instructions?","a":"<p><code>FROM</code>, <code>RUN</code>, <code>CMD</code>, <code>ENTRYPOINT</code>, <code>COPY</code>, <code>ADD</code>, <code>WORKDIR</code>, <code>EXPOSE</code>, <code>ENV</code>.</p>","hand":false},{"id":"docker-f0018","card":"q-docker-006-dockerfile-instructions","sec":"docker-s007","q":"CMD vs ENTRYPOINT?","a":"<ul>\n  <li><strong>CMD</strong>: default arguments, overridable.</li>\n  <li><strong>ENTRYPOINT</strong>: the fixed executable.</li>\n</ul>","hand":false},{"id":"docker-f0019","card":"q-docker-006-dockerfile-instructions","sec":"docker-s007","q":"What is the purpose of <code>.dockerignore</code>?","a":"<p>It excludes files from the build context. Builds are faster and cleaner.</p>","hand":false},{"id":"docker-f0020","card":"q-docker-007-reducing-image-size","sec":"docker-s008","q":"How do you reduce image size?","a":"<p>Use a small base (for example alpine), chain <code>RUN</code> commands, clean up after installs, and use multi-stage builds.</p>","hand":false},{"id":"docker-f0021","card":"q-docker-007-reducing-image-size","sec":"docker-s008","q":"What is a multi-stage build and why use it?","a":"<p>It separates build from runtime, so the final image is smaller.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Dockerfile</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>FROM golang AS builder\nRUN go build -o app\nFROM alpine\nCOPY --from=builder /app .</code></pre></div>","hand":false},{"id":"docker-f0022","card":"q-docker-007-reducing-image-size","sec":"docker-s008","q":"How do you reduce Docker image size in practice (on-call view)?","a":"<p>Use lightweight images, clean up after installs, minimize layers, and copy only the built output from a builder stage.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Dockerfile</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>FROM alpine:latest\nRUN apt-get update &amp;&amp; apt-get install -y &lt;package&gt; &amp;&amp; apt-get clean &amp;&amp; rm -rf /var/lib/apt/lists/*\nFROM node:16 AS builder\nWORKDIR /app\nCOPY package.json .\nRUN npm install\nFROM node:16-slim\nCOPY --from=builder /app /app\nRUN rm -rf /app/unneeded_files</code></pre></div>","hand":false},{"id":"docker-f0023","card":"q-docker-008-multi-architecture-images","sec":"docker-s009","q":"How do you build multi-arch images?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker buildx build --platform linux/amd64,linux/arm64</code></pre></div>","hand":false},{"id":"docker-f0024","card":"q-docker-009-hands-on-build-a-custom-image","sec":"docker-s010","q":"How do you create a container with a custom image from a Dockerfile?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Dockerfile</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code># Dockerfile\nFROM nginx:latest\nCOPY index.html /usr/share/nginx/html/</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker build -t my-nginx .\ndocker run -d -p 80:80 my-nginx</code></pre></div>","hand":false},{"id":"docker-f0025","card":"q-docker-010-starting-and-naming-containers","sec":"docker-s011","q":"How do you start a container detached?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run -d nginx</code></pre></div>","hand":false},{"id":"docker-f0026","card":"q-docker-010-starting-and-naming-containers","sec":"docker-s011","q":"How do you run a container with a specific name?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run --name myapp nginx</code></pre></div>","hand":false},{"id":"docker-f0027","card":"q-docker-010-starting-and-naming-containers","sec":"docker-s011","q":"How do you create a container running Nginx and expose it?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run -d -p 80:80 nginx</code></pre></div>","hand":false},{"id":"docker-f0028","card":"q-docker-010-starting-and-naming-containers","sec":"docker-s011","q":"How do you expose it on port 8080?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run -d -p 8080:80 nginx</code></pre></div>","hand":false},{"id":"docker-f0029","card":"q-docker-010-starting-and-naming-containers","sec":"docker-s011","q":"How do you set an environment variable?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run -d -e MY_VAR=&quot;hello&quot; nginx</code></pre></div>","hand":false},{"id":"docker-f0030","card":"q-docker-011-logs-inspect-and-attach","sec":"docker-s012","q":"How do you view container logs?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker logs &lt;id&gt;\ndocker logs -f &lt;id&gt;  # Real-time logs</code></pre></div>","hand":false},{"id":"docker-f0031","card":"q-docker-011-logs-inspect-and-attach","sec":"docker-s012","q":"How do you inspect a running container?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker inspect &lt;id&gt;</code></pre></div>","hand":false},{"id":"docker-f0032","card":"q-docker-011-logs-inspect-and-attach","sec":"docker-s012","q":"How do you attach to a container terminal?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker attach &lt;id&gt;\ndocker exec -it &lt;id&gt; bash</code></pre></div>","hand":false},{"id":"docker-f0033","card":"q-docker-012-stopping-and-removing-containers","sec":"docker-s013","q":"stop vs kill?","a":"<ul>\n  <li><strong>stop</strong>: graceful (SIGTERM).</li>\n  <li><strong>kill</strong>: instant (SIGKILL).</li>\n</ul>","hand":false},{"id":"docker-f0034","card":"q-docker-012-stopping-and-removing-containers","sec":"docker-s013","q":"<code>rm</code> vs <code>rm -f</code>?","a":"<ul>\n  <li><strong>rm</strong>: removes stopped containers only.</li>\n  <li><strong>rm -f</strong>: stops and removes.</li>\n</ul>","hand":false},{"id":"docker-f0035","card":"q-docker-012-stopping-and-removing-containers","sec":"docker-s013","q":"What happens to data when a container stops?","a":"<p>In-memory data is lost. The file system persists until the container is deleted. Use volumes for durable data.</p>","hand":false},{"id":"docker-f0036","card":"q-docker-013-resource-limits-and-restart-policy","sec":"docker-s014","q":"How do you limit CPU and memory?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run --cpus=&quot;1&quot; -m 512m nginx\ndocker run -d --cpus=&quot;0.5&quot; nginx</code></pre></div>","hand":false},{"id":"docker-f0037","card":"q-docker-013-resource-limits-and-restart-policy","sec":"docker-s014","q":"What is the purpose of <code>--restart</code>?","a":"<p>It sets an auto-restart policy, for example <code>always</code> or <code>on-failure:5</code>.</p>","hand":false},{"id":"docker-f0038","card":"q-docker-014-troubleshooting-a-failing-container","sec":"docker-s015","q":"How do you debug a failing container?","a":"<p>Check logs, inspect it, and run it interactively.</p>","hand":false},{"id":"docker-f0039","card":"q-docker-014-troubleshooting-a-failing-container","sec":"docker-s015","q":"How do you troubleshoot a container that keeps exiting?","a":"<p>Check logs and the exit code, run it interactively, and check the <code>CMD</code>.</p>","hand":false},{"id":"docker-f0040","card":"q-docker-014-troubleshooting-a-failing-container","sec":"docker-s015","q":"A container overuses memory. What do you do?","a":"<p>Check <code>docker stats</code>, cap it with <code>-m</code>, and debug the app.</p>","hand":false},{"id":"docker-f0041","card":"q-docker-014-troubleshooting-a-failing-container","sec":"docker-s015","q":"A failed image build. How do you fix it?","a":"<p>Check the logs, test each step, and rebuild with <code>--no-cache</code>.</p>","hand":false},{"id":"docker-f0042","card":"q-docker-015-network-types-and-the-default-bridge","sec":"docker-s016","q":"What are the types of Docker networks?","a":"<p><strong>Bridge</strong> (default), <strong>Host</strong> (no isolation), <strong>Overlay</strong> (multi-host), <strong>None</strong>, <strong>Macvlan</strong>.</p>","hand":false},{"id":"docker-f0043","card":"q-docker-015-network-types-and-the-default-bridge","sec":"docker-s016","q":"What is the default bridge network?","a":"<p>It uses private IPs and NAT to the host, so port mapping is needed.</p>","hand":false},{"id":"docker-f0044","card":"q-docker-015-network-types-and-the-default-bridge","sec":"docker-s016","q":"Host vs bridge network?","a":"<ul>\n  <li><strong>Host</strong>: uses the host's network stack, no isolation.</li>\n  <li><strong>Bridge</strong>: isolated and NAT'd.</li>\n</ul>","hand":false},{"id":"docker-f0045","card":"q-docker-015-network-types-and-the-default-bridge","sec":"docker-s016","q":"When do you use an overlay network?","a":"<p>For multi-host communication in Swarm, for example distributed apps.</p>","hand":false},{"id":"docker-f0046","card":"q-docker-016-custom-networks-dns-and-communication","sec":"docker-s017","q":"How do you create a custom network?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker network create mynet</code></pre></div>","hand":false},{"id":"docker-f0047","card":"q-docker-016-custom-networks-dns-and-communication","sec":"docker-s017","q":"How do containers communicate?","a":"<p>On the same network, by IP or by name (custom networks). External access needs port mapping.</p>","hand":false},{"id":"docker-f0048","card":"q-docker-016-custom-networks-dns-and-communication","sec":"docker-s017","q":"How does Docker DNS resolution work?","a":"<p>Custom networks resolve container names automatically. The default bridge does not.</p>","hand":false},{"id":"docker-f0049","card":"q-docker-016-custom-networks-dns-and-communication","sec":"docker-s017","q":"What is <code>--link</code> and why is it deprecated?","a":"<p>It links containers on the default bridge. It is outdated; use custom networks.</p>","hand":false},{"id":"docker-f0050","card":"q-docker-017-exposing-ports","sec":"docker-s018","q":"How do you expose a port?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run -p 8080:80 nginx</code></pre></div>","hand":false},{"id":"docker-f0051","card":"q-docker-017-exposing-ports","sec":"docker-s018","q":"EXPOSE vs <code>-p</code>?","a":"<ul>\n  <li><strong>EXPOSE</strong>: documents intent.</li>\n  <li><strong>-p</strong>: actually binds the port.</li>\n</ul>","hand":false},{"id":"docker-f0052","card":"q-docker-018-hands-on-networking-recipes","sec":"docker-s019","q":"How do you create a Docker network for two containers?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker network create my-network\ndocker run -d --name container1 --network my-network nginx\ndocker run -d --name container2 --network my-network busybox</code></pre></div>","hand":false},{"id":"docker-f0053","card":"q-docker-018-hands-on-networking-recipes","sec":"docker-s019","q":"How do you attach a container to a custom network?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker network create custom-network\ndocker run -d --network custom-network nginx</code></pre></div>","hand":false},{"id":"docker-f0054","card":"q-docker-018-hands-on-networking-recipes","sec":"docker-s019","q":"How do you link a container to another container?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run -d --name db mysql:5.7\ndocker run -d --link db:database nginx</code></pre></div>","hand":false},{"id":"docker-f0055","card":"q-docker-019-volumes-vs-bind-mounts","sec":"docker-s020","q":"Volumes vs bind mounts?","a":"<ul>\n  <li><strong>Volumes</strong>: Docker-managed, portable.</li>\n  <li><strong>Binds</strong>: a host path, precise.</li>\n</ul>","hand":false},{"id":"docker-f0056","card":"q-docker-019-volumes-vs-bind-mounts","sec":"docker-s020","q":"What happens to a volume when the container is deleted?","a":"<p>It stays. Volumes live in <code>/var/lib/docker/volumes</code>.</p>","hand":false},{"id":"docker-f0057","card":"q-docker-019-volumes-vs-bind-mounts","sec":"docker-s020","q":"How do you get persistent storage?","a":"<p>Volumes (<code>-v myvol:/data</code>) or binds (<code>-v /host:/data</code>).</p>","hand":false},{"id":"docker-f0058","card":"q-docker-019-volumes-vs-bind-mounts","sec":"docker-s020","q":"<code>--mount</code> vs <code>--volume</code>?","a":"<ul>\n  <li><strong>--mount</strong>: precise, modern.</li>\n  <li><strong>-v</strong>: simple, older.</li>\n</ul>","hand":false},{"id":"docker-f0059","card":"q-docker-020-managing-volumes","sec":"docker-s021","q":"How do you create and manage volumes?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker volume create myvol\ndocker volume ls\ndocker volume rm myvol\ndocker volume prune</code></pre></div>","hand":false},{"id":"docker-f0060","card":"q-docker-020-managing-volumes","sec":"docker-s021","q":"How do you mount a local directory?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run -v /host:/container nginx\ndocker run -d -v /local/path:/usr/share/nginx/html nginx</code></pre></div>","hand":false},{"id":"docker-f0061","card":"q-docker-020-managing-volumes","sec":"docker-s021","q":"How do you create a volume and attach it to a container?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker volume create my-volume\ndocker run -d -v my-volume:/data nginx</code></pre></div>","hand":false},{"id":"docker-f0062","card":"q-docker-021-tmpfs-storage-drivers-and-backup","sec":"docker-s022","q":"What is a tmpfs mount and when do you use it?","a":"<p>RAM-based storage for temporary data.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run --tmpfs /tmp</code></pre></div>","hand":false},{"id":"docker-f0063","card":"q-docker-021-tmpfs-storage-drivers-and-backup","sec":"docker-s022","q":"How do you pick a storage driver?","a":"<p><strong>overlay2</strong> (fast, default) or <strong>devicemapper</strong> (enterprise). Match the OS and workload.</p>","hand":false},{"id":"docker-f0064","card":"q-docker-021-tmpfs-storage-drivers-and-backup","sec":"docker-s022","q":"How do you back up volume data?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run -v myvol:/data busybox tar cvf backup.tar /data</code></pre></div>","hand":false},{"id":"docker-f0065","card":"q-docker-022-compose-basics","sec":"docker-s023","q":"Docker Compose vs Docker?","a":"<ul>\n  <li><strong>Compose</strong>: multi-container orchestration.</li>\n  <li><strong>Docker</strong>: single-container runtime.</li>\n</ul>","hand":false},{"id":"docker-f0066","card":"q-docker-022-compose-basics","sec":"docker-s023","q":"What is the structure of <code>docker-compose.yml</code>?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>version: &quot;3.8&quot;\nservices:\n    web:\n        image: nginx</code></pre></div>","hand":false},{"id":"docker-f0067","card":"q-docker-022-compose-basics","sec":"docker-s023","q":"How do you create a compose file with two services?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code># docker-compose.yml\nversion: &quot;3&quot;\nservices:\n  web:\n     image: nginx\n     ports:\n        - &quot;80:80&quot;\n  app:\n     image: busybox\n     command: sleep 3600</code></pre></div>","hand":false},{"id":"docker-f0068","card":"q-docker-023-running-compose-services","sec":"docker-s024","q":"How do you start and stop Compose services?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker-compose up\ndocker-compose stop\ndocker-compose down</code></pre></div>","hand":false},{"id":"docker-f0069","card":"q-docker-023-running-compose-services","sec":"docker-s024","q":"<code>up</code> vs <code>up -d</code>?","a":"<ul>\n  <li><strong>up</strong>: foreground.</li>\n  <li><strong>up -d</strong>: detached.</li>\n</ul>","hand":false},{"id":"docker-f0070","card":"q-docker-023-running-compose-services","sec":"docker-s024","q":"How do you scale a service?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker-compose up -d --scale web=3</code></pre></div>","hand":false},{"id":"docker-f0071","card":"q-docker-023-running-compose-services","sec":"docker-s024","q":"What does <code>docker-compose down</code> do?","a":"<p>It stops and removes containers and networks. Add <code>--volumes</code> for a full cleanup.</p>","hand":false},{"id":"docker-f0072","card":"q-docker-024-environment-ordering-and-overrides","sec":"docker-s025","q":"How do you define environment variables?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>environment:\n    - KEY=value</code></pre></div>","hand":false},{"id":"docker-f0073","card":"q-docker-024-environment-ordering-and-overrides","sec":"docker-s025","q":"What is the purpose of <code>depends_on</code>?","a":"<p>It sets start order, for example <code>depends_on: [db]</code>.</p>","hand":false},{"id":"docker-f0074","card":"q-docker-024-environment-ordering-and-overrides","sec":"docker-s025","q":"How do you override Compose settings?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker-compose -f base.yml -f override.yml up</code></pre></div>","hand":false},{"id":"docker-f0075","card":"q-docker-024-environment-ordering-and-overrides","sec":"docker-s025","q":"How do you link services in Compose?","a":"<p>They are auto-linked via DNS on the default network.</p>","hand":false},{"id":"docker-f0076","card":"q-docker-025-swarm-concepts","sec":"docker-s026","q":"Swarm vs Kubernetes?","a":"<ul>\n  <li><strong>Swarm</strong>: simple, Docker-native.</li>\n  <li><strong>K8s</strong>: complex, feature-rich.</li>\n</ul>","hand":false},{"id":"docker-f0077","card":"q-docker-025-swarm-concepts","sec":"docker-s026","q":"Manager vs worker node?","a":"<ul>\n  <li><strong>Manager</strong>: runs the cluster.</li>\n  <li><strong>Worker</strong>: runs tasks.</li>\n</ul>","hand":false},{"id":"docker-f0078","card":"q-docker-025-swarm-concepts","sec":"docker-s026","q":"What is the purpose of <code>docker service</code>?","a":"<p>It manages Swarm services: create, list, update.</p>","hand":false},{"id":"docker-f0079","card":"q-docker-025-swarm-concepts","sec":"docker-s026","q":"How does Swarm load balance?","a":"<p>A built-in routing mesh spreads traffic.</p>","hand":false},{"id":"docker-f0080","card":"q-docker-026-creating-and-scaling-services","sec":"docker-s027","q":"How do you initialize Swarm?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker swarm init</code></pre></div>","hand":false},{"id":"docker-f0081","card":"q-docker-026-creating-and-scaling-services","sec":"docker-s027","q":"How do you deploy a Swarm service?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker service create --name web -p 80:80 nginx</code></pre></div>","hand":false},{"id":"docker-f0082","card":"q-docker-026-creating-and-scaling-services","sec":"docker-s027","q":"What is a stack in Swarm?","a":"<p>A multi-service YAML file.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker stack deploy -c stack.yml mystack</code></pre></div>","hand":false},{"id":"docker-f0083","card":"q-docker-026-creating-and-scaling-services","sec":"docker-s027","q":"How do you scale in Swarm?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker service scale web=5</code></pre></div>","hand":false},{"id":"docker-f0084","card":"q-docker-027-updates-rollback-and-node-removal","sec":"docker-s028","q":"How do you update a service with no downtime?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker service update --image nginx:1.19 --update-delay 10s web</code></pre></div>","hand":false},{"id":"docker-f0085","card":"q-docker-027-updates-rollback-and-node-removal","sec":"docker-s028","q":"How do you roll back a Swarm service?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker service rollback web</code></pre></div>","hand":false},{"id":"docker-f0086","card":"q-docker-027-updates-rollback-and-node-removal","sec":"docker-s028","q":"How do you remove a Swarm node?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker swarm leave  # Worker\ndocker node rm &lt;id&gt;  # Manager</code></pre></div>","hand":false},{"id":"docker-f0087","card":"q-docker-027-updates-rollback-and-node-removal","sec":"docker-s028","q":"How do you deploy a multi-container app with Swarm?","a":"<p>Write a stack file, run <code>docker stack deploy</code>, scale, and monitor.</p>","hand":false},{"id":"docker-f0088","card":"q-docker-028-securing-containers","sec":"docker-s029","q":"What are the best practices for securing containers?","a":"<p>Run as non-root, use minimal images, scan images, limit resources, and use secrets.</p>","hand":false},{"id":"docker-f0089","card":"q-docker-028-securing-containers","sec":"docker-s029","q":"How do you run a container as non-root?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Dockerfile</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>RUN useradd -m appuser\nUSER appuser</code></pre></div>","hand":false},{"id":"docker-f0090","card":"q-docker-028-securing-containers","sec":"docker-s029","q":"What are the risks of <code>--privileged</code>?","a":"<p>It gives full host access, a huge security hole.</p>","hand":false},{"id":"docker-f0091","card":"q-docker-028-securing-containers","sec":"docker-s029","q":"What is the role of namespaces and cgroups?","a":"<ul>\n  <li><strong>Namespaces</strong>: isolate.</li>\n  <li><strong>Cgroups</strong>: limit resources.</li>\n</ul>","hand":false},{"id":"docker-f0092","card":"q-docker-028-securing-containers","sec":"docker-s029","q":"How do you set resource limits?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run --cpus=&quot;1&quot; -m 256m</code></pre></div>","hand":false},{"id":"docker-f0093","card":"q-docker-029-content-trust-scanning-and-secrets","sec":"docker-s030","q":"What is Docker Content Trust?","a":"<p>It ensures images are signed.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>DOCKER_CONTENT_TRUST=1</code></pre></div>","hand":false},{"id":"docker-f0094","card":"q-docker-029-content-trust-scanning-and-secrets","sec":"docker-s030","q":"How do you scan an image for vulnerabilities?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker scan nginx:latest</code></pre></div>","hand":false},{"id":"docker-f0095","card":"q-docker-029-content-trust-scanning-and-secrets","sec":"docker-s030","q":"What is a Docker secret?","a":"<p>A way to store sensitive data securely.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker secret create mysecret data</code></pre></div>","hand":false},{"id":"docker-f0096","card":"q-docker-030-restricting-traffic-and-host-access","sec":"docker-s031","q":"How do you restrict container traffic?","a":"<p>Use custom networks, <code>--icc=false</code> and firewall rules.</p>","hand":false},{"id":"docker-f0097","card":"q-docker-030-restricting-traffic-and-host-access","sec":"docker-s031","q":"How do you prevent host file system access?","a":"<p>No binds to the root, read-only mounts, and dropped capabilities.</p>","hand":false},{"id":"docker-f0098","card":"q-docker-031-podman-logging-and-plugins","sec":"docker-s032","q":"Docker vs Podman?","a":"<ul>\n  <li><strong>Docker</strong>: daemon-based.</li>\n  <li><strong>Podman</strong>: daemonless and rootless.</li>\n</ul>","hand":false},{"id":"docker-f0099","card":"q-docker-031-podman-logging-and-plugins","sec":"docker-s032","q":"How does Docker logging work?","a":"<p>It captures stdout. Drivers include <code>json-file</code>, <code>syslog</code> and <code>none</code>.</p>","hand":false},{"id":"docker-f0100","card":"q-docker-031-podman-logging-and-plugins","sec":"docker-s032","q":"What are Docker plugins?","a":"<p>They extend Docker's features.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker plugin install rexray</code></pre></div>","hand":false},{"id":"docker-f0101","card":"q-docker-032-registries","sec":"docker-s033","q":"What is a Docker registry and how do you set up a private one?","a":"<p>A registry stores images.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run -d -p 5000:5000 registry:2</code></pre></div>","hand":false},{"id":"docker-f0102","card":"q-docker-032-registries","sec":"docker-s033","q":"How do you push to Docker Hub?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker push username/myapp:tag</code></pre></div>","hand":false},{"id":"docker-f0103","card":"q-docker-033-health-checks","sec":"docker-s034","q":"What is the purpose of HEALTHCHECK?","a":"<p>It monitors container health.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Dockerfile</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>HEALTHCHECK --interval=30s --timeout=3s --retries=3 CMD curl -f http://localhost/ || exit 1</code></pre></div>","hand":false},{"id":"docker-f0104","card":"q-docker-034-containerizing-apps","sec":"docker-s035","q":"How do you containerize a Node.js app?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Dockerfile</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>FROM node:16\nCOPY . /app\nRUN npm install\nCMD [&quot;node&quot;, &quot;index.js&quot;]</code></pre></div>","hand":false},{"id":"docker-f0105","card":"q-docker-034-containerizing-apps","sec":"docker-s035","q":"How do you write a Dockerfile for a Flask app?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Dockerfile</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>FROM python:3.9-slim\nCOPY requirements.txt .\nRUN pip install -r requirements.txt\nCOPY . .\nCMD [&quot;flask&quot;, &quot;run&quot;, &quot;--host=0.0.0.0&quot;]</code></pre></div>","hand":false},{"id":"docker-f0106","card":"q-docker-034-containerizing-apps","sec":"docker-s035","q":"How do you migrate an app to Docker?","a":"<p>Write the Dockerfile, build and test, add volumes, then deploy.</p>","hand":false},{"id":"docker-f0107","card":"q-docker-035-compose-for-microservices","sec":"docker-s036","q":"How do you use Compose for microservices?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>services:\n    frontend:\n        image: node:16\n        ports: [&quot;3000:3000&quot;]\n    backend:\n        image: python:3.9\n        ports: [&quot;5000:5000&quot;]\n    db:\n        image: postgres:13\n        volumes: [db-data:/var/lib/postgresql/data]\nvolumes:\n    db-data:</code></pre></div>","hand":false},{"id":"docker-f0108","card":"q-docker-036-ci-cd-and-zero-downtime","sec":"docker-s037","q":"How do you do CI/CD with Docker?","a":"<p>Build and push in CI (for example GitHub Actions), then deploy via Compose or Swarm.</p>","hand":false},{"id":"docker-f0109","card":"q-docker-036-ci-cd-and-zero-downtime","sec":"docker-s037","q":"How do you do a zero-downtime update?","a":"<p>Use a Swarm rolling update with <code>docker service update</code>.</p>","hand":false},{"id":"docker-f0110","card":"q-docker-038-running-containers-on-aws-compute","sec":"docker-s039","q":"How do you create a Docker container on an EC2 instance?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code># Run on EC2 instance after SSH\ndocker run -d -p 80:80 nginx</code></pre></div>","hand":false},{"id":"docker-f0111","card":"q-docker-038-running-containers-on-aws-compute","sec":"docker-s039","q":"How do you attach a container to an EBS volume on EC2?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code># Run on EC2 instance with EBS volume mounted at /mnt/ebs\ndocker run -d -v /mnt/ebs:/data nginx</code></pre></div>","hand":false},{"id":"docker-f0112","card":"q-docker-038-running-containers-on-aws-compute","sec":"docker-s039","q":"How do you attach a container to an ECS cluster?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code># Assumes ECS task definition is created via AWS CLI or console\ndocker build -t my-app .\ndocker tag my-app &lt;ECR_REGISTRY&gt;/my-app:latest\ndocker push &lt;ECR_REGISTRY&gt;/my-app:latest\n# Use AWS CLI to run task on ECS\naws ecs run-task --cluster my-ecs-cluster --task-definition my-task --launch-type FARGATE --network-configuration &quot;awsvpcConfiguration={subnets=[subnet-12345678],securityGroups=[sg-12345678]}&quot;</code></pre></div>","hand":false},{"id":"docker-f0113","card":"q-docker-038-running-containers-on-aws-compute","sec":"docker-s039","q":"How do you create a Docker image and push it to Amazon ECR?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker build -t my-app .\ndocker tag my-app &lt;ECR_REGISTRY&gt;/my-app:latest\naws ecr get-login-password --region us-east-1 | docker login --username AWS --password-stdin &lt;ECR_REGISTRY&gt;\ndocker push &lt;ECR_REGISTRY&gt;/my-app:latest</code></pre></div>","hand":false},{"id":"docker-f0114","card":"q-docker-039-load-balancer-dns-and-lambda","sec":"docker-s040","q":"How do you attach a container to a load balancer?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code># Assumes ALB is set up with a target group in AWS\ndocker run -d -p 80:80 --name nginx nginx\n# Register container&#x27;s EC2 instance with ALB target group via AWS CLI\naws elbv2 register-targets --target-group-arn &lt;TARGET_GROUP_ARN&gt; --targets Id=&lt;EC2_INSTANCE_ID&gt;,Port=80</code></pre></div>","hand":false},{"id":"docker-f0115","card":"q-docker-039-load-balancer-dns-and-lambda","sec":"docker-s040","q":"How do you attach a container to a Route 53 domain?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run -d -p 80:80 --name nginx nginx\n# Update Route 53 record via AWS CLI (run separately)\naws route53 change-resource-record-sets --hosted-zone-id &lt;ZONE_ID&gt; --change-batch &#x27;{&quot;Changes&quot;:[{&quot;Action&quot;:&quot;UPSERT&quot;,&quot;ResourceRecordSet&quot;:{&quot;Name&quot;:&quot;nginx.example.com&quot;,&quot;Type&quot;:&quot;A&quot;,&quot;TTL&quot;:300,&quot;ResourceRecords&quot;:[{&quot;Value&quot;:&quot;&lt;EC2_PUBLIC_IP&gt;&quot;}]}}]}&#x27;</code></pre></div>","hand":false},{"id":"docker-f0116","card":"q-docker-039-load-balancer-dns-and-lambda","sec":"docker-s040","q":"How do you attach a container to a Lambda function trigger?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code># Lambda trigger typically set up via AWS console/CLI; container runs app\ndocker run -d -p 8080:8080 my-app\n# Configure Lambda to invoke via API Gateway or event source separately</code></pre></div>","hand":false},{"id":"docker-f0117","card":"q-docker-040-databases-and-caches","sec":"docker-s041","q":"How do you connect a container to an RDS instance?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run -d \\\n  -e MYSQL_HOST=&lt;RDS_ENDPOINT&gt; \\\n  -e MYSQL_USER=admin \\\n  -e MYSQL_PASSWORD=&lt;DB_PASSWORD&gt; \\\n  -e MYSQL_DATABASE=mydb \\\n  mysql:5.7</code></pre></div>","hand":false},{"id":"docker-f0118","card":"q-docker-040-databases-and-caches","sec":"docker-s041","q":"How do you connect a container to a DynamoDB table?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run -d \\\n    -e AWS_ACCESS_KEY_ID=&lt;AWS_ACCESS_KEY_ID&gt; \\\n    -e AWS_SECRET_ACCESS_KEY=&lt;AWS_SECRET_ACCESS_KEY&gt; \\\n    -e AWS_REGION=us-east-1 \\\n    amazon/aws-cli dynamodb list-tables</code></pre></div>","hand":false},{"id":"docker-f0119","card":"q-docker-040-databases-and-caches","sec":"docker-s041","q":"How do you connect a container to a Redis instance?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run -d \\\n    -e REDIS_HOST=&lt;REDIS_ENDPOINT&gt; \\\n    -e REDIS_PORT=6379 \\\n    redis redis-cli -h &lt;REDIS_ENDPOINT&gt; PING</code></pre></div>","hand":false},{"id":"docker-f0120","card":"q-docker-041-s3-sns-and-cloudwatch-logs","sec":"docker-s042","q":"How do you attach a container to an S3 bucket?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run -d \\\n  -e AWS_ACCESS_KEY_ID=&lt;AWS_ACCESS_KEY_ID&gt; \\\n  -e AWS_SECRET_ACCESS_KEY=&lt;AWS_SECRET_ACCESS_KEY&gt; \\\n  -e AWS_REGION=us-east-1 \\\n  amazon/aws-cli s3 ls s3://my-bucket</code></pre></div>","hand":false},{"id":"docker-f0121","card":"q-docker-041-s3-sns-and-cloudwatch-logs","sec":"docker-s042","q":"How do you connect a container to an SNS topic?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run -d \\\n    -e AWS_ACCESS_KEY_ID=&lt;AWS_ACCESS_KEY_ID&gt; \\\n    -e AWS_SECRET_ACCESS_KEY=&lt;AWS_SECRET_ACCESS_KEY&gt; \\\n    -e AWS_REGION=us-east-1 \\\n    amazon/aws-cli sns publish --topic-arn &lt;SNS_TOPIC_ARN&gt; --message &quot;Hello from Docker&quot;</code></pre></div>","hand":false},{"id":"docker-f0122","card":"q-docker-041-s3-sns-and-cloudwatch-logs","sec":"docker-s042","q":"How do you attach a container to a CloudWatch log group?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run -d \\\n    --log-driver=awslogs \\\n    --log-opt awslogs-region=us-east-1 \\\n    --log-opt awslogs-group=my-log-group \\\n    --log-opt awslogs-create-group=true \\\n    nginx</code></pre></div>","hand":false},{"id":"docker-f0123","card":"q-docker-042-container-fails-to-start","sec":"docker-s043","q":"Container fails to start: \"OCI runtime create failed: no such file or directory: /bin/bash\"?","a":"<p>The image lacks <code>/bin/bash</code> or the entrypoint is wrong.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker inspect &lt;image_name&gt; | grep -i entrypoint\ndocker run -it &lt;image_name&gt; /bin/sh -c &quot;ls /bin/bash&quot;</code></pre></div>\n<ul>\n  <li>Install bash: <code>RUN apt-get update &amp;&amp; apt-get install -y bash</code></li>\n  <li>Or use <code>/bin/sh</code>: <code>docker run -it --entrypoint /bin/sh &lt;image_name&gt;</code></li>\n  <li>Ensure the base image has the required shell. Minimal images (for example alpine) may only have <code>sh</code>.</li>\n</ul>","hand":false},{"id":"docker-f0124","card":"q-docker-042-container-fails-to-start","sec":"docker-s043","q":"Container stuck in \"Created\" state?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker ps -a\ndocker inspect &lt;container_id&gt; | jq &#x27;.State.Error&#x27;\njournalctl -u docker.service\ndocker start &lt;container_id&gt;</code></pre></div>\n<ul>\n  <li>Recreate if needed: <code>docker rm &lt;container_id&gt; &amp;&amp; docker run &lt;image_name&gt;</code></li>\n  <li>Verify the Docker daemon (<code>systemctl status docker</code>), resources and architecture compatibility.</li>\n</ul>","hand":false},{"id":"docker-f0125","card":"q-docker-043-memory-and-exit-codes","sec":"docker-s044","q":"Container exits with code 137?","a":"<p>It is an out-of-memory (OOM) kill.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker logs &lt;container_id&gt;\ndocker inspect &lt;container_id&gt; | grep -i memory\ndocker run --memory=&quot;512m&quot; &lt;image_name&gt;</code></pre></div>\n<p>Check host memory (<code>free -m</code>), application leaks, or adjust <code>--memory-swap</code>.</p>","hand":false},{"id":"docker-f0126","card":"q-docker-043-memory-and-exit-codes","sec":"docker-s044","q":"Container fails: \"cannot allocate memory\"?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>free -m\ndocker inspect &lt;container_id&gt; | grep -i memory\ndocker run --memory=&quot;1g&quot; &lt;image_name&gt;\ndocker system prune</code></pre></div>\n<p>Check for memory leaks, make sure the host has memory, and adjust swap settings.</p>","hand":false},{"id":"docker-f0127","card":"q-docker-044-unresponsive-or-unreachable-containers","sec":"docker-s045","q":"Application in the container is not responding?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker exec -it &lt;container_id&gt; /bin/sh\nps aux\ndocker logs &lt;container_id&gt;\ncurl http://localhost:&lt;port&gt;\ndocker stats &lt;container_id&gt;</code></pre></div>\n<p>Check application logs and port binding. Avoid stopping the container while debugging.</p>","hand":false},{"id":"docker-f0128","card":"q-docker-044-unresponsive-or-unreachable-containers","sec":"docker-s045","q":"Container not accessible, possibly not running?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker ps -a | grep &lt;container_name&gt;\ndocker start &lt;container_id&gt;\ndocker logs &lt;container_id&gt;</code></pre></div>\n<ul>\n  <li>Recreate: <code>docker rm &lt;container_id&gt; &amp;&amp; docker run &lt;image_name&gt;</code></li>\n  <li>Verify configuration, the Docker daemon and host resources (<code>df -h</code>, <code>free -m</code>).</li>\n</ul>","hand":false},{"id":"docker-f0129","card":"q-docker-044-unresponsive-or-unreachable-containers","sec":"docker-s045","q":"Container uses excessive CPU?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker stats &lt;container_id&gt;\ndocker exec &lt;container_id&gt; top\ndocker update --cpus=&quot;0.5&quot; &lt;container_id&gt;</code></pre></div>\n<p>Set CPU limits (<code>--cpus</code>), check for application loops, and monitor host CPU (<code>htop</code>).</p>","hand":false},{"id":"docker-f0130","card":"q-docker-045-recreating-scaling-and-updating","sec":"docker-s046","q":"How do you recreate an accidentally deleted container?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker inspect &lt;image_name&gt; | grep -i cmd\ndocker run -d --name &lt;container_name&gt; -p &lt;host_port&gt;:&lt;container_port&gt; -v &lt;volume_path&gt; &lt;image_name&gt;\ndocker-compose up -d</code></pre></div>\n<p>Store configuration in Compose files or scripts, verify volumes, and check environment variables.</p>","hand":false},{"id":"docker-f0131","card":"q-docker-045-recreating-scaling-and-updating","sec":"docker-s046","q":"How do you scale a Dockerized application?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker-compose up -d --scale &lt;service_name&gt;=3\ndocker swarm init\ndocker service create --replicas 3 --name &lt;service_name&gt; &lt;image_name&gt;\ndocker run -d -p 80:80 nginx</code></pre></div>\n<p>NGINX config:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Nginx</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>upstream app {\n    server container1:8080;\n    server container2:8080;\n    server container3:8080;\n}\nserver { listen 80; location / { proxy_pass http://app; } }</code></pre></div>\n<p>The app must be stateless. Monitor resources (<code>docker stats</code>) and use an external load balancer in production.</p>","hand":false},{"id":"docker-f0132","card":"q-docker-045-recreating-scaling-and-updating","sec":"docker-s046","q":"How do you update a container to the latest application version?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker pull &lt;image_name&gt;:latest\ndocker-compose up -d\ndocker service update --image &lt;image_name&gt;:latest &lt;service_name&gt;\ndocker exec &lt;container_id&gt; &lt;app_version_command&gt;</code></pre></div>\n<p>Test in staging, ensure data compatibility, and use health checks.</p>","hand":false},{"id":"docker-f0133","card":"q-docker-046-connectivity-failures","sec":"docker-s047","q":"Container cannot connect to an external database?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker inspect &lt;container_id&gt; | grep -i network\ndocker exec &lt;container_id&gt; ping &lt;db_host&gt;\ndocker exec &lt;container_id&gt; nslookup &lt;db_host&gt;\nsudo iptables -L -n\nsudo iptables -A INPUT -p tcp --dport &lt;db_port&gt; -j ACCEPT</code></pre></div>\n<p>Verify the database host and port, the network mode, and firewall or security groups.</p>","hand":false},{"id":"docker-f0134","card":"q-docker-046-connectivity-failures","sec":"docker-s047","q":"Containers in the same network cannot communicate?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker network ls\ndocker inspect &lt;container_id&gt; | grep -i network\ndocker exec &lt;container1_id&gt; ping &lt;container2_name&gt;\ndocker network create mynet\ndocker network connect mynet &lt;container_id&gt;</code></pre></div>\n<p>Docker Compose:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>version: &#x27;3&#x27;\nservices:\n  app1: { image: &lt;image1&gt;, networks: [mynet] }\n  app2: { image: &lt;image2&gt;, networks: [mynet] }\nnetworks: { mynet: { driver: bridge } }</code></pre></div>\n<p>Use container names for DNS, check network policies, and restart after changes.</p>","hand":false},{"id":"docker-f0135","card":"q-docker-046-connectivity-failures","sec":"docker-s047","q":"Container blocked from an external API by a firewall?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sudo iptables -L -n -v\ndocker exec &lt;container_id&gt; curl &lt;api_url&gt;\nsudo iptables -A OUTPUT -p tcp --dport &lt;api_port&gt; -j ACCEPT\nip route</code></pre></div>\n<p>Verify firewall rules and cloud security groups, then test connectivity.</p>","hand":false},{"id":"docker-f0136","card":"q-docker-047-ports-and-dns","sec":"docker-s048","q":"Containerized app not accessible via the mapped port?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker inspect &lt;container_id&gt; | grep -i port\ndocker exec &lt;container_id&gt; netstat -tuln\ncurl http://localhost:&lt;host_port&gt;\nsudo iptables -L -n\nsudo iptables -A INPUT -p tcp --dport &lt;host_port&gt; -j ACCEPT</code></pre></div>\n<p>Verify the port mapping, that the app binds to <code>0.0.0.0</code>, and that no host service conflicts.</p>","hand":false},{"id":"docker-f0137","card":"q-docker-047-ports-and-dns","sec":"docker-s048","q":"Port conflict: \"Bind for 0.0.0.0:80 failed\"?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sudo netstat -tulnp | grep :80\nsudo kill &lt;pid&gt;\ndocker run -p 8080:80 &lt;image_name&gt;</code></pre></div>\n<p>Check for conflicting containers (<code>docker ps</code>) and avoid duplicate port usage.</p>","hand":false},{"id":"docker-f0138","card":"q-docker-047-ports-and-dns","sec":"docker-s048","q":"Container cannot resolve DNS names?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker exec &lt;container_id&gt; nslookup google.com\ndocker inspect &lt;container_id&gt; | grep -i dns\ndocker run --dns 8.8.8.8 &lt;image_name&gt;\ncat /etc/resolv.conf</code></pre></div>\n<p>Verify host DNS, check network policies (port 53), and restart after DNS changes.</p>","hand":false},{"id":"docker-f0139","card":"q-docker-048-packet-loss-502-errors-and-slowness","sec":"docker-s049","q":"Container dropping packets intermittently?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker inspect &lt;container_id&gt; | grep -i network\ndocker exec &lt;container_id&gt; tcpdump -i eth0\nsudo tcpdump -i docker0\ndocker stats &lt;container_id&gt;</code></pre></div>\n<p>Check for congestion, MTU settings or network driver issues (<code>ifconfig</code>).</p>","hand":false},{"id":"docker-f0140","card":"q-docker-048-packet-loss-502-errors-and-slowness","sec":"docker-s049","q":"Containerized web server returns 502 Bad Gateway?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker logs &lt;container_id&gt;\ndocker exec &lt;web_container_id&gt; curl http://&lt;backend_service&gt;:&lt;port&gt;\ndocker inspect &lt;container_id&gt; | grep -i network</code></pre></div>\n<p>NGINX config:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Nginx</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>server { listen 80; location / { proxy_pass http://&lt;backend_service&gt;:&lt;port&gt;; } }</code></pre></div>\n<p>Verify backend health, network configuration and proxy settings.</p>","hand":false},{"id":"docker-f0141","card":"q-docker-048-packet-loss-502-errors-and-slowness","sec":"docker-s049","q":"Slow container network performance?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker stats &lt;container_id&gt;\ndocker run -it --rm &lt;image_name&gt; iperf -c &lt;target_ip&gt;\nsudo iftop -i docker0\ndocker network inspect &lt;network_name&gt; | grep -i mtu</code></pre></div>\n<p>Compare with other containers, check congestion or QoS, and verify the network driver.</p>","hand":false},{"id":"docker-f0142","card":"q-docker-049-restricting-traffic-between-containers","sec":"docker-s050","q":"How do you restrict network traffic between containers?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker network create --driver bridge --opt com.docker.network.bridge.enable_icc=false mynet\ndocker network connect mynet &lt;container_id&gt;\nsudo iptables -A FORWARD -s &lt;container1_ip&gt; -d &lt;container2_ip&gt; -p tcp --dport &lt;port&gt; -j ACCEPT</code></pre></div>\n<p>Test connectivity, use Compose networks, and avoid blocking critical traffic.</p>","hand":false},{"id":"docker-f0143","card":"q-docker-050-permissions-and-missing-paths","sec":"docker-s051","q":"Container cannot write to a mounted volume?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>ls -ld /path/to/volume\nchmod -R 775 /path/to/volume\nchown -R user:group /path/to/volume\ndocker inspect &lt;container_id&gt; | jq &#x27;.Mounts&#x27;\nsetenforce 0\ndocker restart &lt;container_id&gt;</code></pre></div>\n<p>Align host and container permissions, and check SELinux/AppArmor.</p>","hand":false},{"id":"docker-f0144","card":"q-docker-050-permissions-and-missing-paths","sec":"docker-s051","q":"Bind mount changes not reflected on the host?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker inspect &lt;container_id&gt; | jq &#x27;.Mounts&#x27;\nls -ld /path/to/host/mount\nchmod -R 775 /path/to/host/mount\ndocker exec &lt;container_id&gt; id\ndocker run -v /path/to/host/mount:/app:rw &lt;image_name&gt;\nchcon -R -t container_file_t /path/to/host/mount</code></pre></div>\n<p>Confirm the <code>rw</code> flag, align permissions, and check SELinux.</p>","hand":false},{"id":"docker-f0145","card":"q-docker-050-permissions-and-missing-paths","sec":"docker-s051","q":"Volume error: \"no such file or directory\"?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker volume ls\nls -ld /path/to/host/mount\nmkdir -p /path/to/host/mount\ndocker run -v /path/to/host/mount:/app &lt;image_name&gt;\ncat Dockerfile | grep VOLUME</code></pre></div>\n<p>Ensure the volume or path exists, check path spelling, and verify the Docker commands.</p>","hand":false},{"id":"docker-f0146","card":"q-docker-051-disk-usage","sec":"docker-s052","q":"Volume filling up the host disk?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>du -sh /var/lib/docker/volumes/*\ndocker stop &lt;container_id&gt;\ndocker run --rm -v &lt;volume_name&gt;:/data busybox sh -c &quot;rm -rf /data/unneeded_files&quot;\ndocker volume prune</code></pre></div>\n<p>Stop containers before cleanup, verify files are safe to delete, and use pruning cautiously.</p>","hand":false},{"id":"docker-f0147","card":"q-docker-051-disk-usage","sec":"docker-s052","q":"Unused volumes consuming disk space?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker volume ls\ndocker volume ls -f dangling=true\ndocker volume prune\ndf -h</code></pre></div>\n<p>Verify volume dependencies and avoid accidental data loss.</p>","hand":false},{"id":"docker-f0148","card":"q-docker-052-recovery-migration-and-expansion","sec":"docker-s053","q":"How do you recover a corrupted volume?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker volume inspect &lt;volume_name&gt;\ndocker run --rm -v &lt;volume_name&gt;:/data -it busybox sh\nfsck /path/to/volume\ntar -xzf /backup/volume_backup.tar.gz -C /var/lib/docker/volumes/&lt;volume_name&gt;/_data\ndocker volume create new_volume\ndocker run -v new_volume:/app &lt;image_name&gt;</code></pre></div>\n<p>Maintain backups, test restored data, and use recovery containers.</p>","hand":false},{"id":"docker-f0149","card":"q-docker-052-recovery-migration-and-expansion","sec":"docker-s053","q":"How do you migrate a volume to a new host?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker stop &lt;container_id&gt;\ntar -czf volume_backup.tar.gz -C /var/lib/docker/volumes/&lt;volume_name&gt;/_data .\nscp volume_backup.tar.gz user@new_host:/tmp\ndocker volume create &lt;volume_name&gt;\ntar -xzf /tmp/volume_backup.tar.gz -C /var/lib/docker/volumes/&lt;volume_name&gt;/_data\ndocker run -v &lt;volume_name&gt;:/app &lt;image_name&gt;</code></pre></div>\n<p>Ensure Docker version compatibility, verify permissions, and test after migration.</p>","hand":false},{"id":"docker-f0150","card":"q-docker-052-recovery-migration-and-expansion","sec":"docker-s053","q":"How do you expand database container storage?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker exec &lt;container_id&gt; df -h\ndocker volume create new_volume\ndocker run --rm -v &lt;old_volume&gt;:/old -v new_volume:/new busybox sh -c &quot;cp -a /old/. /new/&quot;\ndocker stop &lt;container_id&gt;\ndocker run -v new_volume:/data &lt;image_name&gt;</code></pre></div>\n<p>Minimize downtime, verify data integrity, and ensure host disk space.</p>","hand":false},{"id":"docker-f0151","card":"q-docker-053-nfs-and-persistence","sec":"docker-s054","q":"Container cannot access an NFS volume?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>ping &lt;nfs_server_ip&gt;\nmount | grep nfs\napt-get install -y nfs-common\nmount -t nfs &lt;nfs_server_ip&gt;:/share /mnt\ndocker inspect &lt;container_id&gt; | jq &#x27;.Mounts&#x27;\ndocker run -v &lt;nfs_server_ip&gt;:/share:/mnt &lt;image_name&gt;</code></pre></div>\n<p>Verify the NFS server, firewall and client tools.</p>","hand":false},{"id":"docker-f0152","card":"q-docker-053-nfs-and-persistence","sec":"docker-s054","q":"How do you ensure data persistence across restarts?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker volume create persistent_volume\ndocker run -v persistent_volume:/app/data &lt;image_name&gt;\ndocker inspect persistent_volume</code></pre></div>\n<p>Use named volumes, back up critical data, and verify mounts.</p>","hand":false},{"id":"docker-f0153","card":"q-docker-054-build-failures","sec":"docker-s055","q":"Build fails: \"COPY failed: no such file or directory\"?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>cat Dockerfile | grep COPY\nls -l ./xyz</code></pre></div>\n<p>Fix: <code>COPY ./xyz /app/xyz</code></p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker build -t my_image .</code></pre></div>\n<p>Verify file paths and that the files are in the build context.</p>","hand":false},{"id":"docker-f0154","card":"q-docker-054-build-failures","sec":"docker-s055","q":"Missing dependency in a custom image?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker logs &lt;container_id&gt;\ncat Dockerfile</code></pre></div>\n<p>Add: <code>RUN apt-get update &amp;&amp; apt-get install -y &lt;dependency&gt;</code></p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker build -t my_image .\ndocker run my_image</code></pre></div>\n<p>Check logs, update the Dockerfile, and test after the rebuild.</p>","hand":false},{"id":"docker-f0155","card":"q-docker-054-build-failures","sec":"docker-s055","q":"Build fails due to a network timeout?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>ping archive.ubuntu.com</code></pre></div>\n<p>Use a mirror: <code>RUN echo \"deb http://mirror.example.com/ubuntu focal main\" &gt; /etc/apt/sources.list</code></p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker build --build-arg APT_TIMEOUT=300 -t my_image .\ndocker build --no-cache -t my_image .</code></pre></div>\n<p>Verify the network, use reliable mirrors, and cache packages locally.</p>","hand":false},{"id":"docker-f0156","card":"q-docker-054-build-failures","sec":"docker-s055","q":"Inconsistent Dockerfile builds?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>cat Dockerfile</code></pre></div>\n<p>Pin versions: <code>FROM node:16.13.2; RUN npm install express@4.17.1</code></p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker build --no-cache -t my_image .\ndocker run -it &lt;builder_image&gt; bash</code></pre></div>\n<p>Pin package versions, avoid variable outputs, and standardize the build environment.</p>","hand":false},{"id":"docker-f0157","card":"q-docker-055-faster-builds","sec":"docker-s056","q":"How do you optimize a Dockerfile for faster builds?","a":"<p>Cache dependencies by copying the dependency file first, use multi-stage builds, and minimize copied files.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Dockerfile</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>COPY requirements.txt .\nRUN pip install -r requirements.txt\nCOPY . .</code></pre></div>\n<p>Multi-stage:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Dockerfile</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>FROM node:16 AS builder\nWORKDIR /app\nCOPY package.json .\nRUN npm install\nFROM node:16-slim\nCOPY --from=builder /app /app</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker build --cache-from my_image:latest -t my_image .</code></pre></div>","hand":false},{"id":"docker-f0158","card":"q-docker-056-registry-and-base-image-problems","sec":"docker-s057","q":"Pulling an outdated image from the registry?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker pull my_image:latest\ndocker image rm my_image:latest\ndocker images my_image\ndocker run my_image:latest</code></pre></div>\n<p>Avoid <code>latest</code> in production, clear the cache, and verify registry credentials.</p>","hand":false},{"id":"docker-f0159","card":"q-docker-056-registry-and-base-image-problems","sec":"docker-s057","q":"Base image unavailable in the registry?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker images\ndocker tag my_image:backup my_image:latest\ndocker search &lt;image_name&gt;</code></pre></div>\n<p>Update: <code>FROM new_image:latest</code></p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker build -t my_image .</code></pre></div>\n<p>Maintain local backups, use specific tags, and test alternatives.</p>","hand":false},{"id":"docker-f0160","card":"q-docker-057-scanning-and-multi-arch","sec":"docker-s058","q":"How do you scan for image vulnerabilities?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>trivy image my_image:latest</code></pre></div>\n<p>Update: <code>RUN apt-get update &amp;&amp; apt-get upgrade -y</code></p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker build -t my_image:latest .\ntrivy image my_image:latest</code></pre></div>\n<p>Use scanners (Trivy/Clair), keep images updated, and retest after updates.</p>","hand":false},{"id":"docker-f0161","card":"q-docker-057-scanning-and-multi-arch","sec":"docker-s058","q":"How do you create a multi-architecture image?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker buildx create --use\ndocker buildx build --platform linux/amd64,linux/arm64 -t my_image:multiarch --push .\ndocker buildx imagetools inspect my_image:multiarch</code></pre></div>\n<p>Ensure buildx is installed, specify the architectures, and push to a registry.</p>","hand":false},{"id":"docker-f0162","card":"q-docker-058-non-root-and-filesystem-restrictions","sec":"docker-s059","q":"How do you run a container as a non-root user?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Dockerfile</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>FROM node:16\nRUN useradd -m appuser\nUSER appuser\nCOPY . /app\nWORKDIR /app\nCMD [&quot;node&quot;, &quot;app.js&quot;]</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run --user appuser &lt;image_name&gt;\ndocker build -t &lt;image_name&gt; .</code></pre></div>\n<p>Verify the app supports non-root and check permissions.</p>","hand":false},{"id":"docker-f0163","card":"q-docker-058-non-root-and-filesystem-restrictions","sec":"docker-s059","q":"How do you restrict container filesystem access?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run --read-only &lt;image_name&gt;\ndocker run -v /host/path:/container/path:ro &lt;image_name&gt;\ndocker run --tmpfs /tmp &lt;image_name&gt;</code></pre></div>\n<p>Avoid sensitive mounts, use read-only, and combine with user namespaces.</p>","hand":false},{"id":"docker-f0164","card":"q-docker-059-capabilities-and-security-policies","sec":"docker-s060","q":"A container bypasses security policies?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker inspect &lt;container_id&gt; | grep CapAdd\ndocker inspect &lt;container_id&gt; | grep Privileged\ndocker run --cap-drop=ALL --cap-add=NET_BIND_SERVICE &lt;image_name&gt;\ndocker run --security-opt apparmor=docker-default &lt;image_name&gt;</code></pre></div>\n<p>Avoid privileged mode, apply AppArmor/SELinux, and audit configurations.</p>","hand":false},{"id":"docker-f0165","card":"q-docker-059-capabilities-and-security-policies","sec":"docker-s060","q":"How do you reduce container capabilities?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker inspect &lt;container_id&gt; | grep CapAdd\ndocker run --cap-drop=ALL --cap-add=CHOWN --cap-add=SETUID &lt;image_name&gt;\ndocker exec &lt;container_id&gt; capsh --print</code></pre></div>\n<p>Drop unnecessary capabilities and test functionality.</p>","hand":false},{"id":"docker-f0166","card":"q-docker-060-investigating-a-compromise","sec":"docker-s061","q":"How do you investigate a compromised container?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker top &lt;container_id&gt;\ndocker logs &lt;container_id&gt;\ndocker run --rm -v /var/run/docker.sock:/var/run/docker.sock aquasec/trivy image &lt;image_name&gt;\ndocker pause &lt;container_id&gt;\ndocker rm -f &lt;container_id&gt;</code></pre></div>\n<p>Quarantine the container, check the network, and rebuild from a trusted source.</p>","hand":false},{"id":"docker-f0167","card":"q-docker-060-investigating-a-compromise","sec":"docker-s061","q":"How do you block unauthorized container network requests?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker network inspect &lt;network_name&gt;\ntcpdump -i docker0\niptables -A OUTPUT -s &lt;container_ip&gt; -j DROP\ndocker run --network none &lt;image_name&gt;</code></pre></div>\n<p>Use network namespaces, firewall rules, and audit ports.</p>","hand":false},{"id":"docker-f0168","card":"q-docker-061-credentials-and-vulnerable-libraries","sec":"docker-s062","q":"How do you remove sensitive credentials from an image?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker history &lt;image_name&gt;\ndocker run --rm -v /var/run/docker.sock:/var/run/docker.sock aquasec/trivy image &lt;image_name&gt;</code></pre></div>\n<p>Rebuild without credentials:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Dockerfile</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>FROM node:16\nCOPY . /app\nWORKDIR /app\nCMD [&quot;node&quot;, &quot;app.js&quot;]</code></pre></div>\n<p>Use secrets or environment variables, and squash layers.</p>","hand":false},{"id":"docker-f0169","card":"q-docker-061-credentials-and-vulnerable-libraries","sec":"docker-s062","q":"How do you update a vulnerable library in a container?","a":"<p>Scan with the same Trivy command, then update: <code>FROM node:16; RUN apt-get update &amp;&amp; apt-get upgrade -y</code></p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker build -t &lt;image_name&gt;:latest .\ndocker push &lt;image_name&gt;:latest</code></pre></div>\n<p>Update base images, automate scans, and test compatibility.</p>","hand":false},{"id":"docker-f0170","card":"q-docker-062-access-control-and-registry-trust","sec":"docker-s063","q":"How do you implement Docker role-based access control?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>useradd -m dockeruser\ngroupadd docker\nusermod -aG docker dockeruser\nchown root:docker /var/run/docker.sock\nchmod 660 /var/run/docker.sock\ndocker context create restricted --docker host=unix:///var/run/docker.sock</code></pre></div>\n<p>Limit the <code>docker</code> group, use TLS, and audit permissions.</p>","hand":false},{"id":"docker-f0171","card":"q-docker-062-access-control-and-registry-trust","sec":"docker-s063","q":"How do you verify a registry for malicious images?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run --rm -v /var/run/docker.sock:/var/run/docker.sock aquasec/trivy image &lt;registry&gt;/&lt;image_name&gt;\ndocker trust inspect &lt;registry&gt;/&lt;image_name&gt;\ndocker pull --disable-content-trust=false &lt;registry&gt;/&lt;image_name&gt;\ndocker login &lt;registry&gt;</code></pre></div>\n<p>Use trusted registries, enable Docker Content Trust, and scan regularly.</p>","hand":false},{"id":"docker-f0172","card":"q-docker-063-compose-problems","sec":"docker-s064","q":"Docker Compose \"service not found\" error?","a":"<p>Check <code>docker-compose.yml</code> for the service definition, validate syntax (<code>docker-compose config</code>), and restart (<code>docker-compose up -d</code>). Verify service names, file paths and the Compose version.</p>","hand":false},{"id":"docker-f0173","card":"q-docker-063-compose-problems","sec":"docker-s064","q":"Compose service communication failure?","a":"<p>Verify the network (<code>docker network inspect &lt;network&gt;</code>), test connectivity (<code>docker exec &lt;container&gt; ping &lt;service&gt;</code>), and ensure service names resolve. Check DNS, firewall and network configuration.</p>","hand":false},{"id":"docker-f0174","card":"q-docker-063-compose-problems","sec":"docker-s064","q":"Compose ignores environment variables?","a":"<p>Verify <code>docker-compose.yml</code> (<code>env_file</code> or <code>environment</code>), check the container (<code>docker inspect &lt;container&gt; | grep Env</code>), and restart (<code>docker-compose up -d</code>). Validate variable syntax and avoid overrides.</p>","hand":false},{"id":"docker-f0175","card":"q-docker-063-compose-problems","sec":"docker-s064","q":"Compose crashes due to resource limits?","a":"<p>Check limits (<code>docker inspect &lt;container&gt;</code>), adjust <code>docker-compose.yml</code> (<code>mem_limit: 512m</code>, <code>cpus: 0.5</code>), and restart (<code>docker-compose up -d</code>). Monitor resource usage and balance limits.</p>","hand":false},{"id":"docker-f0176","card":"q-docker-063-compose-problems","sec":"docker-s064","q":"Compose file startup errors?","a":"<p>Validate syntax (<code>docker-compose config</code>), check logs (<code>docker-compose logs</code>), fix errors, and restart (<code>docker-compose up -d</code>). Verify service dependencies and image availability.</p>","hand":false},{"id":"docker-f0177","card":"q-docker-064-swarm-problems","sec":"docker-s065","q":"Swarm service stuck in \"pending\"?","a":"<p>Check node resources (<code>docker node ls</code>), logs (<code>docker service logs &lt;service&gt;</code>) and constraints. Scale or adjust (<code>docker service update</code>). Ensure enough nodes and check placement constraints.</p>","hand":false},{"id":"docker-f0178","card":"q-docker-064-swarm-problems","sec":"docker-s065","q":"Swarm service not scaling?","a":"<p>Check resources (<code>docker node ls</code>), update replicas (<code>docker service scale &lt;service&gt;=3</code>), and review logs (<code>docker service logs &lt;service&gt;</code>). Ensure node capacity and check constraints.</p>","hand":false},{"id":"docker-f0179","card":"q-docker-064-swarm-problems","sec":"docker-s065","q":"Swarm node marked \"Down\"?","a":"<p>Check status (<code>docker node ls</code>) and logs (<code>journalctl -u docker</code>), then restart the node (<code>docker node update --availability active &lt;node&gt;</code>). Verify the network, the Docker daemon and node health.</p>","hand":false},{"id":"docker-f0180","card":"q-docker-064-swarm-problems","sec":"docker-s065","q":"Swarm service not load balancing?","a":"<p>Check the routing mesh (<code>docker network inspect ingress</code>), verify replicas (<code>docker service ps &lt;service&gt;</code>), and test endpoints (<code>curl &lt;node_ip&gt;</code>). Ensure correct ports and check the load balancer config.</p>","hand":false},{"id":"docker-f0181","card":"q-docker-065-rolling-updates","sec":"docker-s066","q":"How do you do a rolling update for a Swarm service?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker service update --image &lt;image&gt;:latest &lt;service&gt; --update-parallelism 1 --update-delay 10s</code></pre></div>\n<p>Test updates, ensure health checks, and monitor with <code>docker service ps &lt;service&gt;</code>.</p>","hand":false},{"id":"docker-f0182","card":"q-docker-066-finding-bottlenecks","sec":"docker-s067","q":"High latency in a Dockerized app?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker stats\ntop -p $(pidof dockerd)\niostat -x 1\nnetstat -i</code></pre></div>\n<p>Check CPU, memory, disk and network bottlenecks. Correlate container and host metrics.</p>","hand":false},{"id":"docker-f0183","card":"q-docker-066-finding-bottlenecks","sec":"docker-s067","q":"A slow containerized app?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker stats &lt;container_name&gt;\ndocker top &lt;container_name&gt;\niostat -x 1\nnetstat -tunap</code></pre></div>\n<p>Check resources, processes, disk and network. Correlate with logs and identify contention.</p>","hand":false},{"id":"docker-f0184","card":"q-docker-066-finding-bottlenecks","sec":"docker-s067","q":"How do you analyze high load with Linux tools?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>top\nhtop\nsar -u 1 5\nsar -r 1 5</code></pre></div>\n<p>Identify high-CPU and high-memory processes and check trends. Look for Docker processes and monitor historical data.</p>","hand":false},{"id":"docker-f0185","card":"q-docker-067-memory-disk-and-network","sec":"docker-s068","q":"Periodic memory spikes?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker stats &lt;container_name&gt;\ndocker inspect &lt;container_name&gt; | grep Memory\nsmem -k -p -c pss,uss</code></pre></div>\n<p>Monitor spikes, check limits, and analyze processes. Verify application activity and check for leaks.</p>","hand":false},{"id":"docker-f0186","card":"q-docker-067-memory-disk-and-network","sec":"docker-s068","q":"Excessive container disk I/O?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>iostat -x 1\niotop -o -P\ndocker inspect &lt;container_name&gt; | grep Mounts</code></pre></div>\n<p>Identify high-I/O processes and check mounts. Optimize app I/O and check host issues.</p>","hand":false},{"id":"docker-f0187","card":"q-docker-067-memory-disk-and-network","sec":"docker-s068","q":"Network bottlenecks on the Docker host?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>iftop -i eth0\nnload eth0\ndocker network inspect bridge</code></pre></div>\n<p>Monitor traffic and check container network config. Identify high-traffic containers and check policies.</p>","hand":false},{"id":"docker-f0188","card":"q-docker-068-monitoring-setup-benchmarking-and-profil","sec":"docker-s069","q":"How do you set up monitoring?","a":"<p>Monitor CPU, memory, I/O and network with Prometheus and Grafana.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run -d --name prometheus -p 9090:9090 -v /path/to/prometheus.yml:/etc/prometheus/prometheus.yml prom/prometheus\ndocker run -d --name grafana -p 3000:3000 grafana/grafana</code></pre></div>\n<p>Configure Prometheus scraping and set alerts.</p>","hand":false},{"id":"docker-f0189","card":"q-docker-068-monitoring-setup-benchmarking-and-profil","sec":"docker-s069","q":"How do you benchmark container performance?","a":"<p>Simulate load and monitor metrics.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run -it &lt;container_name&gt; stress --cpu 2 --io 1 --vm 1 --vm-bytes 128M --timeout 60s\ndocker stats &lt;container_name&gt;\nperf stat -p $(docker top &lt;container_name&gt; | awk &#x27;NR&gt;1 {print $2}&#x27;)</code></pre></div>\n<p>Use realistic workloads and compare against baselines.</p>","hand":false},{"id":"docker-f0190","card":"q-docker-068-monitoring-setup-benchmarking-and-profil","sec":"docker-s069","q":"How do you profile container CPU usage?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker stats &lt;container_name&gt;\ndocker top &lt;container_name&gt;\nperf stat -p $(docker top &lt;container_name&gt; | awk &#x27;NR&gt;1 {print $2}&#x27;)\ndocker update --cpus=&quot;0.5&quot; &lt;container_name&gt;</code></pre></div>\n<p>Monitor and limit CPU usage. Identify intensive processes and balance limits.</p>","hand":false},{"id":"docker-f0191","card":"q-docker-068-monitoring-setup-benchmarking-and-profil","sec":"docker-s069","q":"How do you capture intermittent container crashes?","a":"<p>Stream logs, monitor events, and use Promtail/Loki.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker logs &lt;container_name&gt; --follow\ndocker events --filter &#x27;container=&lt;container_name&gt;&#x27;\ndocker run -d --name promtail -v /var/log:/var/log loki/promtail -config.file=/etc/promtail/promtail.yml</code></pre></div>\n<p>Correlate crashes with resources and ensure log capture.</p>","hand":false},{"id":"docker-f0192","card":"q-docker-069-missing-or-verbose-logs","sec":"docker-s070","q":"No logs from the containerized app?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker inspect &lt;container_name&gt; | grep LogConfig\ndocker run --log-driver=json-file --log-opt max-size=10m &lt;container_name&gt;\ndocker logs &lt;container_name&gt;</code></pre></div>\n<p>Configure the <code>json-file</code> driver and verify logs. Ensure the app writes to stdout/stderr and check driver compatibility.</p>","hand":false},{"id":"docker-f0193","card":"q-docker-069-missing-or-verbose-logs","sec":"docker-s070","q":"How do you increase log verbosity for crashes?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker inspect &lt;container_name&gt; | grep LogConfig\ndocker run --log-driver=json-file --log-opt max-size=50m &lt;container_name&gt; --verbose\ndocker logs &lt;container_name&gt;</code></pre></div>\n<p>Enable verbose mode and increase log size. Verify the app supports verbose and monitor storage.</p>","hand":false},{"id":"docker-f0194","card":"q-docker-069-missing-or-verbose-logs","sec":"docker-s070","q":"How do you enable debugging for silent failures?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run --log-driver=json-file --log-opt max-size=10m &lt;container_name&gt; --debug\ndocker events --filter &#x27;container=&lt;container_name&gt;&#x27;\ndocker logs &lt;container_name&gt;</code></pre></div>\n<p>Enable debug and monitor events and logs. Verify debug support and check the config for suppressed logs.</p>","hand":false},{"id":"docker-f0195","card":"q-docker-069-missing-or-verbose-logs","sec":"docker-s070","q":"How do you redirect container logs to a file?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run --log-driver=json-file --log-opt max-size=10m -v /host/path:/logs &lt;container_name&gt;\ndocker exec &lt;container_name&gt; sh -c &#x27;echo &quot;log output&quot; &gt; /logs/app.log&#x27;</code></pre></div>\n<p>Use a volume for log files. Check permissions and monitor log growth.</p>","hand":false},{"id":"docker-f0196","card":"q-docker-070-centralized-logging","sec":"docker-s071","q":"How do you collect logs from multiple containers, or centralize logs from multiple hosts?","a":"<p>Use Loki and Promtail for aggregation and query via Grafana.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker run -d --name loki -p 3100:3100 grafana/loki\ndocker run -d --name promtail -v /var/lib/docker/containers:/var/lib/docker/containers loki/promtail -config.file=/etc/promtail/promtail.yml</code></pre></div>\n<p>Ensure Promtail has access, configure retention, ensure connectivity between hosts, and secure with TLS.</p>","hand":false},{"id":"docker-f0197","card":"q-docker-071-debugging-inside-containers","sec":"docker-s072","q":"How do you debug a container process with <code>strace</code> or <code>gdb</code>?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker exec -it &lt;container_name&gt; apt-get update &amp;&amp; apt-get install -y strace gdb\ndocker exec -it &lt;container_name&gt; strace -p $(pgrep process_name)\ndocker exec -it &lt;container_name&gt; gdb --pid=$(pgrep process_name)</code></pre></div>\n<p>Ensure the tools are available and avoid impacting production.</p>","hand":false},{"id":"docker-f0198","card":"q-docker-071-debugging-inside-containers","sec":"docker-s072","q":"How do you confirm a container memory leak?","a":"<p>Use <code>valgrind</code> to detect leaks.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker exec -it &lt;container_name&gt; apt-get update &amp;&amp; apt-get install -y valgrind\ndocker exec -it &lt;container_name&gt; valgrind --leak-check=full --log-file=/tmp/valgrind.log process_name</code></pre></div>\n<p>Ensure debug symbols and account for overhead.</p>","hand":false},{"id":"docker-f0199","card":"q-docker-071-debugging-inside-containers","sec":"docker-s072","q":"How do you extract context from cryptic errors?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker logs &lt;container_name&gt; --tail 100\ndocker inspect &lt;container_name&gt; | grep Env\ndocker exec &lt;container_name&gt; cat /path/to/config</code></pre></div>\n<p>Review logs, environment and configs. Correlate errors with settings and enable debug mode.</p>","hand":false},{"id":"docker-f0200","card":"q-docker-072-host-journal-logs","sec":"docker-s073","q":"How do you manage excessive journald logs?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>journalctl --disk-usage\njournalctl --vacuum-size=500M\nsudo vi /etc/systemd/journald.conf\n# Set: SystemMaxUse=500M\nsudo systemctl restart systemd-journald</code></pre></div>\n<p>Reduce log size and set limits. Balance retention and monitor after changes.</p>","hand":false},{"id":"docker-f0201","card":"q-docker-073-restarting-and-restoring","sec":"docker-s074","q":"How do you auto-restart containers after a host crash?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sudo systemctl enable docker\ndocker run --restart=always -d &lt;image_name&gt;\ndocker update --restart=always &lt;container_id&gt;</code></pre></div>\n<p>Use an appropriate restart policy, verify resources, and check logs.</p>","hand":false},{"id":"docker-f0202","card":"q-docker-073-restarting-and-restoring","sec":"docker-s074","q":"How do you restore a critical containerized app?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker-compose -f docker-compose.yml up -d\ndocker run -d --name &lt;container_name&gt; -p &lt;port&gt;:&lt;port&gt; -v &lt;volume&gt; &lt;image_name&gt;\ndocker ps -a</code></pre></div>\n<p>Store configs, ensure the image and volume are available, and test restoration.</p>","hand":false},{"id":"docker-f0203","card":"q-docker-074-backups-and-restores","sec":"docker-s075","q":"How do you back up a Dockerized database?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker exec &lt;mysql_container&gt; mysqldump -u root -p&lt;password&gt; --all-databases &gt; backup.sql\nscp backup.sql user@remote_host:/backups/\necho &quot;0 2 * * * docker exec &lt;mysql_container&gt; mysqldump -u root -p&lt;password&gt; --all-databases &gt; /backups/backup_$(date +\\%F).sql&quot; | crontab -</code></pre></div>\n<p>Use app-specific tools, encrypt backups, and test restoration.</p>","hand":false},{"id":"docker-f0204","card":"q-docker-074-backups-and-restores","sec":"docker-s075","q":"How do you restore a corrupted volume?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker stop &lt;container_id&gt;\ntar -xzf /backups/volume_backup.tar.gz -C /var/lib/docker/volumes/&lt;volume_name&gt;\ndocker start &lt;container_id&gt;\ndocker exec &lt;container_id&gt; ls /data</code></pre></div>\n<p>Back up regularly, verify integrity, and test the app after the restore.</p>","hand":false},{"id":"docker-f0205","card":"q-docker-074-backups-and-restores","sec":"docker-s075","q":"How do you recover from filesystem corruption?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sudo fsck /dev/sdX\nsudo apt remove docker.io\nsudo apt install docker.io\ndocker-compose -f docker-compose.yml up -d\ntar -xzf /backups/volume_backup.tar.gz -C /var/lib/docker/volumes/</code></pre></div>\n<p>Back up <code>/var/lib/docker</code>, verify the filesystem, and test containers.</p>","hand":false},{"id":"docker-f0206","card":"q-docker-075-swarm-recovery","sec":"docker-s076","q":"How do you recover a Swarm cluster after manager loss?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker node ls\ndocker node promote &lt;worker_node_id&gt;\ndocker swarm init --force-new-cluster --advertise-addr &lt;manager_ip&gt;:2377\ndocker swarm join --token &lt;worker_token&gt; &lt;manager_ip&gt;:2377</code></pre></div>\n<p>Maintain an odd number of managers, back up Swarm state, and verify health.</p>","hand":false},{"id":"docker-f0207","card":"q-docker-075-swarm-recovery","sec":"docker-s076","q":"How do you simulate a Docker host failure?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sudo systemctl stop docker\ndocker node update --availability drain &lt;node_id&gt;\ndocker service ps &lt;service_name&gt;\nsudo systemctl start docker\ndocker node update --availability active &lt;node_id&gt;</code></pre></div>\n<p>Ensure replicas exist, test backups, monitor availability, and document the steps.</p>","hand":false},{"id":"docker-f0208","card":"q-docker-076-malware-recovery","sec":"docker-s077","q":"How do you recover a Docker host from malware?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sudo ip link set eth0 down\ndocker stop $(docker ps -q)\nsudo apt install clamav\nclamscan -r / --remove\nsudo apt update &amp;&amp; sudo apt upgrade -y\nsudo systemctl restart docker\ndocker start $(docker ps -a -q)</code></pre></div>\n<p>Block malicious traffic, scan images, and restore from clean backups.</p>","hand":false},{"id":"docker-f0209","card":"q-docker-077-high-availability-and-failover","sec":"docker-s078","q":"How do you ensure high availability?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker swarm init\ndocker service create --name app --replicas 3 -p 80:80 &lt;image_name&gt;\nHEALTHCHECK --interval=30s --timeout=3s CMD curl -f http://localhost/ || exit 1\ndocker service update --health-cmd=&quot;curl -f http://localhost/ || exit 1&quot; --health-interval=30s app</code></pre></div>\n<p>Use multiple nodes, a load balancer, and health monitoring.</p>","hand":false},{"id":"docker-f0210","card":"q-docker-077-high-availability-and-failover","sec":"docker-s078","q":"How do you implement failover for frequent outages?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>docker swarm init\ndocker service create --name app --replicas 3 -p 80:80 &lt;image_name&gt;</code></pre></div>\n<p>NGINX config:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Nginx</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>upstream app {\n    server &lt;node1_ip&gt;:80;\n    server &lt;node2_ip&gt;:80;\n    server &lt;node3_ip&gt;:80;\n}\nserver { listen 80; location / { proxy_pass http://app; } }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sudo systemctl reload nginx</code></pre></div>\n<p>Spread replicas, use health checks, and test failover.</p>","hand":false}];
